+/****************************************************************************
+ * SPDX-License-Identifier: Apache-2.0
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#include <stdbool.h>
+#include <stdint.h>
+
+#include <nuttx/clock.h>
+#include <nuttx/irq.h>
+#include <nuttx/wdog.h>
+
+#include <arch/board/board.h>
+
+enum bk7258_led_mode_e
+{
+  BK7258_LED_OFF,
+  BK7258_LED_ON,
+  BK7258_LED_BLINK,
+  BK7258_LED_ALTERNATE
+};
+
+struct bk7258_led_s
+{
+  struct wdog_s timer;
+  uint32_t remaining_ms;
+  uint16_t interval_ms;
+  uint8_t pin;
+  uint8_t mode;
+  bool on;
+};
+
+static struct bk7258_led_s g_leds[BOARD_NLEDS] =
+{
+  {
+    .pin = BOARD_LED_RED_GPIO,
+  },
+  {
+    .pin = BOARD_LED_GREEN_GPIO,
+  }
+};
+
+static bool g_leds_initialized;
+
+void bk7258_gpio_output(unsigned int pin, bool value);
+void bk7258_gpio_write(unsigned int pin, bool value);
+
+static void bk7258_led_write(unsigned int led, bool on)
+{
+  g_leds[led].on = on;
+  bk7258_gpio_write(g_leds[led].pin, on);
+}
+
+static bool bk7258_led_timeout(struct bk7258_led_s *led)
+{
+  if (led->remaining_ms == LED_LAST_FOREVER)
+    {
+      return false;
+    }
+
+  if (led->remaining_ms <= led->interval_ms)
+    {
+      led->remaining_ms = 0;
+      return true;
+    }
+
+  led->remaining_ms -= led->interval_ms;
+  return false;
+}
+
+static void bk7258_led_timer(wdparm_t arg)
+{
+  unsigned int led_id = (unsigned int)arg;
+  struct bk7258_led_s *led = &g_leds[led_id];
+  irqstate_t flags;
+
+  flags = enter_critical_section();
+
+  if (led->mode == BK7258_LED_ON)
+    {
+      bk7258_led_write(led_id, false);
+      led->mode = BK7258_LED_OFF;
+    }
+  else if (led->mode == BK7258_LED_BLINK)
+    {
+      if (bk7258_led_timeout(led))
+        {
+          bk7258_led_write(led_id, false);
+          led->mode = BK7258_LED_OFF;
+        }
+      else
+        {
+          bk7258_led_write(led_id, !led->on);
+          wd_start(&led->timer, MSEC2TICK(led->interval_ms),
+                   bk7258_led_timer, led_id);
+        }
+    }
+  else if (led_id == BOARD_LED_RED &&
+           led->mode == BK7258_LED_ALTERNATE)
+    {
+      bk7258_led_write(BOARD_LED_RED, !g_leds[BOARD_LED_RED].on);
+      bk7258_led_write(BOARD_LED_GREEN, !g_leds[BOARD_LED_GREEN].on);
+      wd_start(&led->timer, MSEC2TICK(led->interval_ms),
+               bk7258_led_timer, BOARD_LED_RED);
+    }
+
+  leave_critical_section(flags);
+}
+
+static void bk7258_led_stop_alternate(void)
+{
+  if (g_leds[BOARD_LED_RED].mode == BK7258_LED_ALTERNATE ||
+      g_leds[BOARD_LED_GREEN].mode == BK7258_LED_ALTERNATE)
+    {
+      wd_cancel(&g_leds[BOARD_LED_RED].timer);
+      g_leds[BOARD_LED_RED].mode = BK7258_LED_OFF;
+      g_leds[BOARD_LED_GREEN].mode = BK7258_LED_OFF;
+      bk7258_led_write(BOARD_LED_RED, false);
+      bk7258_led_write(BOARD_LED_GREEN, false);
+    }
+}
+
+static void bk7258_led_set(unsigned int led_id, uint8_t mode,
+                           uint16_t interval_ms, uint32_t time)
+{
+  struct bk7258_led_s *led = &g_leds[led_id];
+  irqstate_t flags;
+
+  flags = enter_critical_section();
+  bk7258_led_stop_alternate();
+  wd_cancel(&led->timer);
+
+  led->mode = mode;
+  led->interval_ms = interval_ms;
+  led->remaining_ms = time;
+
+  if (mode == BK7258_LED_OFF)
+    {
+      bk7258_led_write(led_id, false);
+    }
+  else
+    {
+      bk7258_led_write(led_id, true);
+
+      if (mode == BK7258_LED_BLINK || time != LED_LAST_FOREVER)
+        {
+          uint32_t delay = mode == BK7258_LED_BLINK ? interval_ms : time;
+
+          wd_start(&led->timer, MSEC2TICK(delay), bk7258_led_timer, led_id);
+        }
+    }
+
+  leave_critical_section(flags);
+}
+
+void led_driver_init(void)
+{
+  irqstate_t flags;
+  unsigned int i;
+
+  flags = enter_critical_section();
+  if (!g_leds_initialized)
+    {
+      for (i = 0; i < BOARD_NLEDS; i++)
+        {
+          wd_init(&g_leds[i].timer);
+          bk7258_gpio_output(g_leds[i].pin, false);
+          g_leds[i].mode = BK7258_LED_OFF;
+          g_leds[i].on = false;
+        }
+
+      g_leds_initialized = true;
+    }
+
+  leave_critical_section(flags);
+}
+
+void led_app_set(led_operate_t oper, uint32_t time)
+{
+  irqstate_t flags;
+
+  led_driver_init();
+
+  switch (oper)
+    {
+      case LED_OFF_GREEN:
+        bk7258_led_set(BOARD_LED_GREEN, BK7258_LED_OFF, 0, 0);
+        break;
+      case LED_ON_GREEN:
+        bk7258_led_set(BOARD_LED_GREEN, BK7258_LED_ON, 0, time);
+        break;
+      case LED_FAST_BLINK_GREEN:
+        bk7258_led_set(BOARD_LED_GREEN, BK7258_LED_BLINK,
+                       LED_FAST_BLINK_TIME, time);
+        break;
+      case LED_SLOW_BLINK_GREEN:
+        bk7258_led_set(BOARD_LED_GREEN, BK7258_LED_BLINK,
+                       LED_SLOW_BLINK_TIME, time);
+        break;
+      case LED_OFF_RED:
+        bk7258_led_set(BOARD_LED_RED, BK7258_LED_OFF, 0, 0);
+        break;
+      case LED_ON_RED:
+        bk7258_led_set(BOARD_LED_RED, BK7258_LED_ON, 0, time);
+        break;
+      case LED_FAST_BLINK_RED:
+        bk7258_led_set(BOARD_LED_RED, BK7258_LED_BLINK,
+                       LED_FAST_BLINK_TIME, time);
+        break;
+      case LED_SLOW_BLINK_RED:
+        bk7258_led_set(BOARD_LED_RED, BK7258_LED_BLINK,
+                       LED_SLOW_BLINK_TIME, time);
+        break;
+      case LED_REG_GREEN_ALTERNATE:
+        flags = enter_critical_section();
+        bk7258_led_stop_alternate();
+        wd_cancel(&g_leds[BOARD_LED_RED].timer);
+        wd_cancel(&g_leds[BOARD_LED_GREEN].timer);
+        g_leds[BOARD_LED_RED].mode = BK7258_LED_ALTERNATE;
